/bin/sh -lc "python3 - <<'PY'
import os, signal, subprocess
rows = [tuple(map(int, line.split())) for line in subprocess.check_output(['ps', '-eo', 'pid=,ppid='], text=True).splitlines()]
owned = {831}
while True:
    more = {pid for pid, parent in rows if parent in owned}
    if more <= owned:
        break
    owned |= more
for pid in sorted(owned, reverse=True):
    try:
        os.kill(pid, signal.SIGTERM)
    except ProcessLookupError:
        pass
print('Stopped the earlier regression run before the final run.')
PY"

